"""Order totals for the shop. Amounts are whole cents (int).

All arithmetic is exact (fractions, never binary floats). Every rounding to
whole cents is round-half-up: an exact half goes up, so 242.5 cents is 243.
"""

import math
from fractions import Fraction


def _exact(value):
    """Convert a number to an exact Fraction.

    A float is read in its usual decimal notation (8.25 means exactly 8.25),
    so binary floating-point error never enters the arithmetic.
    """
    if isinstance(value, float):
        return Fraction(repr(value))
    return Fraction(value)


def _round_half_up(value):
    """Round an exact Fraction to the nearest int, exact halves going up."""
    return math.floor(value + Fraction(1, 2))


def line_total(unit_price_cents, quantity, discount_percent=0):
    """Price of one order line in cents after the percentage discount."""
    amount = _exact(unit_price_cents) * _exact(quantity) * (1 - _exact(discount_percent) / 100)
    return _round_half_up(amount)


def tax(amount_cents, rate_percent):
    """Tax on an amount, in cents."""
    return _round_half_up(_exact(amount_cents) * _exact(rate_percent) / 100)


def order_total(lines, tax_rate_percent=0, shipping_cents=0):
    """Total of an order. `lines` is a list of (unit_price_cents, quantity, discount_percent)."""
    subtotal = sum(line_total(*line) for line in lines)
    return subtotal + tax(subtotal, tax_rate_percent) + shipping_cents


def split_evenly(total_cents, parts):
    """Split a total into `parts` shares that sum to exactly `total_cents`.

    The shares differ by at most one cent and the larger shares come first,
    e.g. split_evenly(100, 3) == [34, 33, 33].
    """
    if parts < 1:
        raise ValueError("parts must be at least 1")
    base, extra = divmod(total_cents, parts)
    return [base + 1] * extra + [base] * (parts - extra)
